const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const validSource=s=>{try{const u=new URL(s);return u.protocol==='https:'&&(u.hostname==='minecraft.wiki'||u.hostname.endsWith('.minecraft.wiki'))}catch{return false}};
async function digest(s){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s)))).map(v=>v.toString(16).padStart(2,'0')).join('')}
async function handler(request,env){const url=new URL(request.url),path=url.pathname;if(!env.BUCKET)return json({error:'Storage unavailable'},503);if(request.method==='OPTIONS'){const origin=request.headers.get('Origin');return new Response(null,{status:204,headers:origin==='https://blockwise.local'?{'Access-Control-Allow-Origin':origin,'Access-Control-Allow-Methods':'GET,PUT,POST,DELETE,OPTIONS','Access-Control-Allow-Headers':'Content-Type,Authorization','Vary':'Origin'}:{}});}if(request.method!=='GET'&&request.headers.get('Origin')&&request.headers.get('Origin')!==url.origin&&request.headers.get('Origin')!=='https://blockwise.local')return json({error:'Origin rejected'},403);
if(Number(request.headers.get('Content-Length')||0)>16000)return json({error:'Too large'},413);let data;if(request.method==='POST'||request.method==='PUT'){if(!request.headers.get('Content-Type')?.startsWith('application/json'))return json({error:'JSON required'},415);const body=await request.text();if(body.length>16000)return json({error:'Too large'},413);try{data=JSON.parse(body)}catch{return json({error:'Invalid JSON'},400)}if(!data||typeof data!=='object'||Array.isArray(data))return json({error:'Invalid data'},400)}
if(path==='/api/submissions'&&request.method==='POST'){if(data.website)return json({error:'Rejected'},400);if(!['report','suggestion'].includes(data.kind)||!['en','es'].includes(data.language)||typeof data.fact!=='string'||data.fact.trim().length<5||data.fact.length>300||typeof data.details!=='string'||data.details.trim().length<5||data.details.length>3000||typeof data.source!=='string'||data.source.length>500||!validSource(data.source))return json({error:'Invalid submission'},400);
// Best-effort per-IP hourly throttle. Add Turnstile/edge rate limiting for public high-traffic deployment.
const rateKey='limits/'+await digest((request.headers.get('CF-Connecting-IP')||'local')+new Date().toISOString().slice(0,13)),old=await env.BUCKET.get(rateKey),count=old?Number(await old.text()):0;if(count>=8)return json({error:'Try later'},429);await env.BUCKET.put(rateKey,String(count+1));const id=crypto.randomUUID();await env.BUCKET.put('submissions/'+new Date().toISOString().slice(0,10)+'/'+id+'.json',JSON.stringify({id,kind:data.kind,fact:data.fact.trim(),source:data.source,details:data.details.trim(),factId:typeof data.factId==='string'?data.factId.slice(0,50):'',language:data.language,status:'pending',createdAt:new Date().toISOString()}),{httpMetadata:{contentType:'application/json'}});return json({id,status:'pending'},201)}
if(path==='/api/progress'){const token=request.headers.get('Authorization')?.replace(/^Bearer /,'');if(!token||!/^[a-f0-9]{48}$/.test(token))return json({error:'Invalid recovery code'},401);const key='progress/'+await digest(token)+'.json';if(request.method==='GET'){const stored=await env.BUCKET.get(key);return stored?json(await stored.json()):json({error:'Not found'},404)}if(request.method==='DELETE'){await env.BUCKET.delete(key);return json({deleted:true})}if(request.method==='PUT'){if(!['en','es'].includes(data.language)||!['light','dark'].includes(data.theme)||!['saved','read','topics'].every(k=>Array.isArray(data[k])&&data[k].length<=500&&data[k].every(s=>typeof s==='string'&&s.length<=50)))return json({error:'Invalid backup'},400);await env.BUCKET.put(key,JSON.stringify({language:data.language,theme:data.theme,saved:data.saved,read:data.read,topics:data.topics}),{httpMetadata:{contentType:'application/json'}});return json({saved:true})}}return json({error:'Not found'},404)}

async function api(request,env){const response=await handler(request,env);if(request.headers.get("Origin")==="https://blockwise.local"){response.headers.set("Access-Control-Allow-Origin","https://blockwise.local");response.headers.set("Vary","Origin");}return response;}

const ASSETS={"/app.js":{"type":"text/javascript; charset=utf-8","body":""},"/facts.json":{"type":"application/json","body":""},"/icon-192.png":{"type":"image/png","body":""},"/icon-512.png":{"type":"image/png","body":""},"/icon.svg":{"type":"image/svg+xml","body":""},"/":{"type":"text/html; charset=utf-8","body":""},"/manifest.webmanifest":{"type":"application/manifest+json","body":""},"/style.css":{"type":"text/css; charset=utf-8","body":""},"/sw.js":{"type":"text/javascript; charset=utf-8","body":""}};
export default {async fetch(request,env){try{const path=new URL(request.url).pathname;if(path.startsWith("/api/"))return await api(request,env);const a=ASSETS[path];if(!a)return new Response("Not found",{status:404});if(!["GET","HEAD"].includes(request.method))return new Response("Method not allowed",{status:405});return new Response(request.method==="HEAD"?null:Uint8Array.from(atob(a.body),c=>c.charCodeAt(0)),{headers:{"Content-Type":a.type,"Cache-Control":path==="/sw.js"?"no-cache":"public, max-age=0, must-revalidate","X-Content-Type-Options":"nosniff","Referrer-Policy":"strict-origin-when-cross-origin","Content-Security-Policy":"default-src \'self\'; script-src \'self\'; style-src \'self\' https://fonts.googleapis.com; font-src \'self\' https://fonts.gstatic.com; img-src \'self\' data:; connect-src \'self\'; object-src \'none\'; base-uri \'self\'; frame-ancestors \'self\'"}})}catch{return Response.json({error:"Service unavailable"},{status:503})}}};